using System.Reflection;
using System.Runtime.CompilerServices;
using System.Text.Json;
using HarmonyLib;
using CombatSolver.Engine.Common;
using CombatSolver.Engine.InCombat.Simulation;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.Entities.Players;
using MegaCrit.Sts2.Core.Hooks;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.Models.Cards;
using MegaCrit.Sts2.Core.ValueProps;

namespace CombatSolver.Engine.Common;

internal static class NativeNoOpProof
{
    [ThreadStatic] internal static bool Disabled;
    [ThreadStatic] private static CombatPredictionSimulator? _patchSimulator;
    [ThreadStatic] private static Player? _patchPlayer;
    [ThreadStatic] private static int _patchCalls;
    [ThreadStatic] private static bool _throw;
    private static readonly InvalidOperationException Failure = new("Native no-op proof injected failure");
    private static readonly (string Name, NativeHookNoOpMask Mask)[] Hooks = [
        (nameof(AbstractModel.ShouldPayExcessEnergyCostWithStars), NativeHookNoOpMask.ExcessStarPayment),
        (nameof(AbstractModel.ModifyUnblockedDamageTarget), NativeHookNoOpMask.UnblockedDamageTarget),
        (nameof(AbstractModel.ShouldEtherealTrigger), NativeHookNoOpMask.EtherealTrigger),
    ];

    internal static string Verify(CombatState live, CombatPredictionSimulator parent, Player player,
        Creature target, Func<CombatPredictionSimulator, string> stamp)
    {
        using IDisposable isolation = SimulationNotificationIsolation.Enter();
        string liveBefore = ContinuationStamp.CaptureLive(live).StateText;
        string parentBefore = stamp(parent);
        AbstractModel[] models = ModelDb.All.ToArray();
        var metadata = MirroredHookListenerFilter.Capture();
        MirroredHookListenerLayout? layout = null;
        metadata.Filter(models, ref layout);
        if (layout == null || !layout.Matches(models)) throw new InvalidOperationException("Missing native layout.");
        foreach (MirroredHookMask mask in Enum.GetValues<MirroredHookMask>())
        {
            if (mask == MirroredHookMask.All) continue;
            string[] names = mask switch {
                MirroredHookMask.GoldCallbacks => [nameof(AbstractModel.ModifyGoldGained),
                    nameof(AbstractModel.AfterModifyingGoldGained), nameof(AbstractModel.AfterGoldGained)],
                MirroredHookMask.ExtraTurnCallbacks => [nameof(AbstractModel.ShouldTakeExtraTurn), nameof(AbstractModel.AfterTakingExtraTurn)],
                _ => [mask.ToString()] };
            for (int i = 0; i < models.Length; i++)
            {
                Type type = models[i].GetType();
                bool expected = type.Assembly != typeof(AbstractModel).Assembly || type.Assembly.IsDynamic
                    || type.GetMethods(BindingFlags.Public | BindingFlags.Instance).Any(method => names.Contains(method.Name)
                        && method.DeclaringType != typeof(AbstractModel) && method.GetBaseDefinition().DeclaringType == typeof(AbstractModel));
                if (((layout.Entries[i].Mask & mask) != 0) != expected)
                    throw new InvalidOperationException("Existing mirrored participation changed: " + type.Name + ":" + mask);
            }
        }
        var participants = new Dictionary<string, string[]>();
        foreach ((string name, NativeHookNoOpMask mask) in Hooks)
        {
            var expected = models.Where(model => model.GetType().Assembly != typeof(AbstractModel).Assembly
                || model.GetType().Assembly.IsDynamic
                || model.GetType().GetMethods(BindingFlags.Public | BindingFlags.Instance).Any(method =>
                    method.Name == name && method.DeclaringType != typeof(AbstractModel)
                    && method.GetBaseDefinition().DeclaringType == typeof(AbstractModel))).ToArray();
            participants[name] = expected.Select(x => x.GetType().Name).Distinct().ToArray();
            if (layout.HasNativeParticipant(mask) != (expected.Length != 0))
                throw new InvalidOperationException("Native participant union differs: " + name);
            foreach (AbstractModel model in models)
            {
                MirroredHookListenerLayout? single = null;
                metadata.Filter([model], ref single);
                if (single == null || single.HasNativeParticipant(mask) != expected.Contains(model))
                    throw new InvalidOperationException("Native participant differs: " + model.GetType().Name + ":" + name);
            }
        }
        var unc = new MirroredHookListenerFilter(true);
        MirroredHookListenerLayout? unaudited = null;
        unc.Filter([ModelDb.Card<StrikeIronclad>()], ref unaudited);
        if (unaudited == null || !unaudited.HasNativeParticipant(NativeHookNoOpMask.All))
            throw new InvalidOperationException("Unaudited native metadata was certified.");
        Console.WriteLine("NATIVE_NOOP_PARTICIPANTS " + JsonSerializer.Serialize(participants));

        CombatPredictionSimulator query = parent.Fork();
        SimulatedCombatState combat = (SimulatedCombatState)query.State.CombatState;
        PredictedCard card = PredictedCard.Create(ModelDb.Card<StrikeIronclad>(), player);
        query.AddToPile(card, PileType.Hand);
        string queryBefore = stamp(query);
        foreach ((_, NativeHookNoOpMask mask) in Hooks)
        {
            if (!MirroredHookListenerFilter.HasNoNativeParticipants(combat, mask))
                throw new InvalidOperationException("Default root did not exercise native bypass: " + mask);
            foreach (decimal amount in new[] {0m, 1m, -1m, 3.5m, decimal.MaxValue})
            {
                object expected = Oracle(query, player, card, target, amount, mask);
                object actual = Guarded(query, player, card, target, amount, mask);
                if (!Equals(expected, actual) || stamp(query) != queryBefore)
                    throw new InvalidOperationException("Native default read changed full state: " + mask);
            }
        }

        // Exercise production CanPlay/ManualPlay, both damage paths, ethereal flush and COW.
        string Execute(bool disabled)
        {
            CombatPredictionSimulator branch = parent.Fork();
            Disabled = disabled;
            try
            {
                var pcs = branch.State.GetPlayerCombatState(player);
                pcs.LoseEnergy(pcs.Energy);
                PredictedCard strike = PredictedCard.Create(ModelDb.Card<StrikeIronclad>(), player);
                PredictedCard ethereal = PredictedCard.Create(ModelDb.Card<DefendIronclad>(), player);
                ethereal.MutablePreview.AddKeyword(CardKeyword.Ethereal);
                branch.AddToPile(strike, PileType.Hand);
                branch.AddToPile(ethereal, PileType.Hand);
                if (branch.CanPlay(strike)) throw new InvalidOperationException("Energy shortage became playable.");
                pcs.GainEnergy(5);
                if (!branch.ManualPlay(strike, target, out _) || branch.HasPendingChoice)
                    throw new InvalidOperationException("Strike failed in native no-op action proof.");
                if (!branch.SimulateEndPlayerTurnBeforeOrbPassives(1) || branch.HasPendingChoice)
                    throw new InvalidOperationException("Ethereal flush failed in native no-op proof.");
                return stamp(branch);
            }
            finally { Disabled = false; }
        }
        if (Execute(true) != Execute(false) || stamp(parent) != parentBefore)
            throw new InvalidOperationException("Production native guards changed full action state/history/RNG.");
        Parallel.For(0, 16, index =>
        {
            using IDisposable parallelIsolation = SimulationNotificationIsolation.Enter();
            CombatPredictionSimulator child;
            lock (parent) child = parent.Fork();
            SimulatedCombatState childCombat = (SimulatedCombatState)child.State.CombatState;
            PredictedCard c = PredictedCard.Create(ModelDb.Card<StrikeIronclad>(), player);
            child.AddToPile(c, PileType.Hand);
            string before = stamp(child);
            foreach ((_, NativeHookNoOpMask mask) in Hooks)
                if (!Equals(Oracle(child, player, c, target, index, mask), Guarded(child, player, c, target, index, mask)))
                    throw new InvalidOperationException("Parallel native default differs.");
            if (stamp(child) != before) throw new InvalidOperationException("Parallel native read changed state.");
        });

        var harmony = new Harmony("CombatSolver.Tests.NativeNoOpProof");
        foreach ((string name, NativeHookNoOpMask mask) in Hooks)
        foreach (Type declaring in new[] {typeof(AbstractModel), typeof(Hook)})
        {
            MethodInfo method = declaring.GetMethod(name)!;
            MethodInfo prefix = typeof(NativeNoOpProof).GetMethod(
                mask == NativeHookNoOpMask.UnblockedDamageTarget ? nameof(TargetPrefix) : nameof(BoolPrefix),
                BindingFlags.Static | BindingFlags.NonPublic)!;
            try
            {
                harmony.Patch(method, prefix: new HarmonyMethod(prefix));
                CombatPredictionSimulator patched = CombatRootSnapshot.Capture(live).ForkSimulator();
                SimulatedCombatState pc = (SimulatedCombatState)patched.State.CombatState;
                PredictedCard patchedCard = PredictedCard.Create(ModelDb.Card<StrikeIronclad>(), player);
                patched.AddToPile(patchedCard, PileType.Hand);
                if (MirroredHookListenerFilter.HasNoNativeParticipants(pc, mask))
                    throw new InvalidOperationException("Patched native/base method retained native certificate.");
                foreach (bool throwing in new[] {false, true})
                {
                    (string State, object? Result, Exception? Error, int Calls) Run(bool guarded)
                    {
                        CombatPredictionSimulator branch = patched.Fork();
                        PredictedCard branchCard = branch.State.GetPlayerCombatState(player).AllCards
                            .Single(c => ReferenceEquals(c.Original, patchedCard.Original));
                        _patchSimulator = branch; _patchPlayer = player; _patchCalls = 0; _throw = throwing;
                        object? result = null; Exception? error = null;
                        try { result = guarded ? Guarded(branch, player, branchCard, target, 7m, mask)
                            : Oracle(branch, player, branchCard, target, 7m, mask); }
                        catch (InvalidOperationException caught) when (ReferenceEquals(caught, Failure)) { error = caught; }
                        finally { _patchSimulator = null; _patchPlayer = null; _throw = false; }
                        return (stamp(branch), result, error, _patchCalls);
                    }
                    var a = Run(false); var c = Run(true);
                    if (a.Calls == 0 || a.Calls != c.Calls || a.State != c.State
                        || !Equals(a.Result, c.Result) || !ReferenceEquals(a.Error, c.Error)
                        || throwing && !ReferenceEquals(a.Error, Failure))
                        throw new InvalidOperationException("Patched native/base effects or exception differ: " + declaring.Name + "." + name
                            + $" throwing={throwing} calls={a.Calls}/{c.Calls} stateEqual={a.State == c.State} resultEqual={Equals(a.Result,c.Result)}"
                            + $" errorEqual={ReferenceEquals(a.Error,c.Error)} tupleEqual={a == c}");
                }
            }
            finally { harmony.Unpatch(method, prefix); }
        }
        if (stamp(parent) != parentBefore || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Native default proof changed parent or live state.");
        // A rejected source must not be evaluated by the guard and then evaluated again
        // by native fallback. Preserve this counterexample before withdrawing v1.
        (int Reads, int Hp, string Stamp) UnknownSource(bool guarded)
        {
            CombatPredictionSimulator branch = parent.Fork();
            var proxy = DispatchProxy.Create<INativeNoOpProofSource, NativeNoOpProofSourceProxy>();
            var data = (NativeNoOpProofSourceProxy)(object)proxy;
            data.Simulator = branch; data.Player = player; data.Model = ModelDb.Card<StrikeIronclad>();
            Creature result = guarded && MirroredHookListenerFilter.HasNoNativeParticipants(proxy,
                    NativeHookNoOpMask.UnblockedDamageTarget) ? target
                : Hook.ModifyUnblockedDamageTarget(proxy, target, 7m, ValueProp.Move, player.Creature);
            if (!ReferenceEquals(result, target)) throw new InvalidOperationException("Unknown source changed damage target.");
            return (data.Reads, branch.State.GetCreature(player.Creature).CurrentHp, stamp(branch));
        }
        var unknownA = UnknownSource(false); var unknownC = UnknownSource(true);
        if (unknownA.Reads != 1 || unknownC.Reads != 2 || unknownC.Hp != unknownA.Hp - 1
            || unknownA.Stamp == unknownC.Stamp || stamp(parent) != parentBefore
            || ContinuationStamp.CaptureLive(live).StateText != liveBefore)
            throw new InvalidOperationException("Unknown-source duplicate getter counterexample was not reproduced.");
        Console.WriteLine("NATIVE_NOOP_PROOF " + JsonSerializer.Serialize(new { models=models.Length, hooks=3, forks=16, patches=6, fullActions=true }));
        return "NativeNoOpGuardsEvidence:" + JsonSerializer.Serialize(new { models=models.Length, hooks=3,
            forks=16, patches=6, participants, unknownSource=new { baselineReads=unknownA.Reads,
                candidateReads=unknownC.Reads, baselineHp=unknownA.Hp, candidateHp=unknownC.Hp,
                fullStatesDiffer=true, parentAndLiveUnchanged=true, candidateSafeForUnknownSources=false },
            baseIl=Hooks.ToDictionary(x => x.Name, x => Convert.ToHexString(typeof(AbstractModel)
                .GetMethod(x.Name)!.GetMethodBody()!.GetILAsByteArray()!)) });
    }

    [MethodImpl(MethodImplOptions.NoInlining)]
    private static object Oracle(CombatPredictionSimulator sim, Player player, PredictedCard card,
        Creature target, decimal amount, NativeHookNoOpMask mask) => mask switch
    {
        NativeHookNoOpMask.ExcessStarPayment => Hook.ShouldPayExcessEnergyCostWithStars(sim.State.CombatState, player),
        NativeHookNoOpMask.UnblockedDamageTarget => Hook.ModifyUnblockedDamageTarget(sim.State.CombatState, target, amount, ValueProp.Move, player.Creature),
        NativeHookNoOpMask.EtherealTrigger => Hook.ShouldEtherealTrigger(sim.State.CombatState, card.Preview),
        _ => throw new InvalidOperationException("Unknown proof hook"),
    };
    private static object Guarded(CombatPredictionSimulator sim, Player player, PredictedCard card,
        Creature target, decimal amount, NativeHookNoOpMask mask)
        => MirroredHookListenerFilter.HasNoNativeParticipants(sim.State.CombatState, mask)
            ? mask switch { NativeHookNoOpMask.ExcessStarPayment => false,
                NativeHookNoOpMask.EtherealTrigger => true, NativeHookNoOpMask.UnblockedDamageTarget => target,
                _ => throw new InvalidOperationException("Unknown proof guard") }
            : Oracle(sim, player, card, target, amount, mask);
    private static void RecordPatch()
    {
        _patchCalls++;
        _patchSimulator!.State.GetCreature(_patchPlayer!.Creature).CurrentHp--;
        if (_throw) throw Failure;
    }
    private static bool BoolPrefix(MethodBase __originalMethod, ref bool __result)
    {
